-- Stub rows for anything the class references that the catalog lacks.
-- The "STUB" marker is load-bearing: it is how the gear importer later
-- recognises a row as still needing stats.
INSERT OR IGNORE INTO gear (slug, name, system, description, source_book) VALUES ('wet-suit', 'Wet Suit', 'rifts', 'STUB ' || char(8212) || ' created by class import, needs stats', 'Rifts World Book 7: Underseas p.60-61');
